#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAXN 100005

typedef struct {
    int x, y;
    char type;
} Point;

Point pts[MAXN];
int n;

// Disjoint Set Union (Union-Find) for grouping points that can be reached
int parent[MAXN];
int rank[MAXN];

void dsu_init() {
    for (int i = 0; i < n; i++) {
        parent[i] = i;
        rank[i] = 0;
    }
}

int dsu_find(int x) {
    if (parent[x] != x)
        parent[x] = dsu_find(parent[x]);
    return parent[x];
}

void dsu_union(int a, int b) {
    int ra = dsu_find(a);
    int rb = dsu_find(b);
    if (ra == rb) return;
    if (rank[ra] < rank[rb]) {
        parent[ra] = rb;
    } else if (rank[ra] > rank[rb]) {
        parent[rb] = ra;
    } else {
        parent[rb] = ra;
        rank[ra]++;
    }
}

// Comparison for sorting by x then y
int cmp_xy(const void *a, const void *b) {
    Point *pa = (Point*)a;
    Point *pb = (Point*)b;
    if (pa->x != pb->x) return pa->x - pb->x;
    return pa->y - pb->y;
}

// Comparison for sorting by y then x
int cmp_yx(const void *a, const void *b) {
    Point *pa = (Point*)a;
    Point *pb = (Point*)b;
    if (pa->y != pb->y) return pa->y - pb->y;
    return pa->x - pb->x;
}

