    // Sort by x then y
    qsort(pts, n, sizeof(Point), cmp_xy);
    for (int i = 0; i < n; ) {
        int j = i;
        while (j < n && pts[j].x == pts[i].x) j++;
        // For consecutive points in same x, if both have 'L' or 'R' type, they can connect
        for (int k = i; k < j - 1; k++) {
            if ((pts[k].type == 'L' || pts[k].type == 'R') && 
                (pts[k+1].type == 'L' || pts[k+1].type == 'R')) {
                dsu_union(k, k+1);
            }
        }
        i = j;
    }

    // Group points that share same y coordinate and have types that allow vertical linking
    qsort(pts, n, sizeof(Point), cmp_yx);
    for (int i = 0; i < n; ) {
        int j = i;
