#define MAXN 1005

int n;
int x[MAXN], y[MAXN], dir[MAXN];
// dir: 0=+x, 1=-x, 2=+y, 3=-y
int dp[MAXN];
int memo[MAXN]; // -1 = not computed

int solve(int i);

int solve(int i) {
    if (memo[i] != -1) return memo[i];
    memo[i] = 1;
    for (int j = 0; j < n; j++) {
        if (i == j) continue;
        // Can we go from i to j?
        int d = dir[i];
        int ok = 0;
        if (d == 0 && y[j] == y[i] && x[j] > x[i]) ok = 1;
        if (d == 1 && y[j] == y[i] && x[j] < x[i]) ok = 1;
        if (d == 2 && x[j] == x[i] && y[j] > y[i]) ok = 1;
        if (d == 3 && x[j] == x[i] && y[j] < y[i]) ok = 1;
        if (ok) {
            int val = 1 + solve(j);
            if (val > memo[i]) memo[i] = val;
        }
    }
    return memo[i];
}

