        else if (c[0]=='+' && c[1]=='y') dir[i]=2;
        else dir[i]=3;
    }
    memset(memo, -1, sizeof(memo));
    int ans = 0;
    for (int i = 0; i < n; i++) {
        int v = solve(i);
        if (v > ans) ans = v;
    }
    printf("%d\n", ans);
