static int cmp_xy(const void *a, const void *b) {
    const Point *p = (const Point*)a;
    const Point *q = (const Point*)b;
    if (p->y != q->y) return (p->y < q->y) ? -1 : 1;
    if (p->x != q->x) return (p->x < q->x) ? -1 : 1;
    return p->t - q->t;
}

static int cmp_yx(const void *a, const void *b) {
    const Point *p = (const Point*)a;
    const Point *q = (const Point*)b;
    if (p->x != q->x) return (p->x < q->x) ? -1 : 1;
    if (p->y != q->y) return (p->y < q->y) ? -1 : 1;
    return p->t - q->t;
}

typedef struct {
    ll a, b;
    int idx;
} Keyed;

static int cmp_row(const void *a, const void *b) {
    const Keyed *p = (const Keyed*)a;
    const Keyed *q = (const Keyed*)b;
    if (p->a != q->a) return (p->a < q->a) ? -1 : 1; // y
    if (p->b != q->b) return (p->b < q->b) ? -1 : 1; // x
    return p->idx - q->idx;
}

static int cmp_col(const void *a, const void *b) {
    const Keyed *p = (const Keyed*)a;
    const Keyed *q = (const Keyed*)b;
    if (p->a != q->a) return (p->a < q->a) ? -1 : 1; // x
    if (p->b != q->b) return (p->b < q->b) ? -1 : 1; // y
    return p->idx - q->idx;
}

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    Point *p = (Point*)malloc(sizeof(Point) * n);
    for (int i = 0; i < n; i++) {
        char s[8];
        scanf("%lld %lld %s", &p[i].x, &p[i].y, s);
        if (strcmp(s, "+x") == 0) p[i].t = 0;
        else if (strcmp(s, "-x") == 0) p[i].t = 1;
        else if (strcmp(s, "+y") == 0) p[i].t = 2;
        else p[i].t = 3; // -y
    }

    int *rightBest = (int*)calloc(n, sizeof(int));
    int *leftBest  = (int*)calloc(n, sizeof(int));
    int *upBest    = (int*)calloc(n, sizeof(int));
    int *downBest  = (int*)calloc(n, sizeof(int));
    int *dp        = (int*)calloc(n, sizeof(int));

    Keyed *rows = (Keyed*)malloc(sizeof(Keyed) * n);
    Keyed *cols = (Keyed*)malloc(sizeof(Keyed) * n);

    for (int i = 0; i < n; i++) {
        rows[i].a = p[i].y; rows[i].b = p[i].x; rows[i].idx = i;
        cols[i].a = p[i].x; cols[i].b = p[i].y; cols[i].idx = i;
    }

    qsort(rows, n, sizeof(Keyed), cmp_row);
    qsort(cols, n, sizeof(Keyed), cmp_col);

    /*
      Iterate several times until stabilization.
      In practice this converges quickly for intended instances.
    */
    int changed = 1;
    for (int iter = 0; iter < n && changed; iter++) {
        changed = 0;

        // Row sweeps: leftBest / rightBest from current dp
        for (int i = 0; i < n; ) {
            int j = i;
            while (j < n && rows[j].a == rows[i].a) j++;

            int best = 0;
            for (int k = i; k < j; k++) {
                int id = rows[k].idx;
                leftBest[id] = best;
                if (dp[id] > best) best = dp[id];
            }

            best = 0;
            for (int k = j - 1; k >= i; k--) {
                int id = rows[k].idx;
                rightBest[id] = best;
                if (dp[id] > best) best = dp[id];
            }

            i = j;
        }

        // Column sweeps: downBest / upBest from current dp
        for (int i = 0; i < n; ) {
            int j = i;
            while (j < n && cols[j].a == cols[i].a) j++;

            int best = 0;
            for (int k = i; k < j; k++) {
                int id = cols[k].idx;
                downBest[id] = best;
                if (dp[id] > best) best = dp[id];
            }

            best = 0;
            for (int k = j - 1; k >= i; k--) {
                int id = cols[k].idx;
                upBest[id] = best;
                if (dp[id] > best) best = dp[id];
            }

            i = j;
        }

        for (int i = 0; i < n; i++) {
            int ndp;
            if (p[i].t == 0) ndp = 1 + rightBest[i];
            else if (p[i].t == 1) ndp = 1 + leftBest[i];
            else if (p[i].t == 2) ndp = 1 + upBest[i];
            else ndp = 1 + downBest[i];

            if (ndp != dp[i]) {
                dp[i] = ndp;
                changed = 1;
            }
        }
    }

    int ans = 0;
    for (int i = 0; i < n; i++) {
        if (dp[i] > ans) ans = dp[i];
    }

    printf("%d\n", ans);

    free(p);
    free(rightBest);
    free(leftBest);
    free(upBest);
    free(downBest);
    free(dp);
    free(rows);
    free(cols);
    return 0;
}

