int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;
    vector<int> x(n), y(n), t(n);
    for (int i = 0; i < n; i++) {
        cin >> x[i] >> y[i] >> t[i];
    }

    // dp[mask][last] = maximum possible log2(speed) after using set 'mask' of points,
    // ending at point 'last' (or -1 for starting state)
    vector<vector<int>> dp(1 << n, vector<int>(n, -1e9));

    // Starting state: we can start from any point with speed 1 (log2 = 0)
    for (int i = 0; i < n; i++) {
        dp[1 << i][i] = 0; // speed = 1 => log2 = 0
    }

    int ans = 0; // we can always achieve at least speed 1 => log2 = 0

    for (int mask = 1; mask < (1 << n); mask++) {
        for (int last = 0; last < n; last++) {
            if (!(mask & (1 << last))) continue;
            int cur_log = dp[mask][last];
            if (cur_log < 0) continue; // unreachable

            ans = max(ans, cur_log);

            // Try to go to another point
            for (int nxt = 0; nxt < n; nxt++) {
                if (mask & (1 << nxt)) continue;
                // Check if we can reach nxt from last
                bool can_reach = false;
                if (t[last] == 1) { // veers parallel to x-axis
                    // After hitting last, direction becomes horizontal (x-axis)
                    // We can go to nxt if same y coordinate
                    if (y[last] == y[nxt]) can_reach = true;
                } else if (t[last] == 2) { // veers parallel to y-axis
                    // After hitting last, direction becomes vertical (y-axis)
                    if (x[last] == x[nxt]) can_reach = true;
                }

                if (can_reach) {
                    int new_mask = mask | (1 << nxt);
                    dp[new_mask][nxt] = max(dp[new_mask][nxt], cur_log + 1);
                }
            }
        }
    }

    cout << ans << "\n";

    return 0;
}

