        // T: 0=+x,1=-x,2=+y,3=-y
        vector<vector<int>> adj(n);
        for(int i=0;i<n;i++){
            for(int j=0;j<n;j++){
                if(i==j) continue;
                if(T[i]==0 && Y[j]==Y[i] && X[j]>X[i]) adj[i].push_back(j);
                else if(T[i]==1 && Y[j]==Y[i] && X[j]<X[i]) adj[i].push_back(j);
                else if(T[i]==2 && X[j]==X[i] && Y[j]>Y[i]) adj[i].push_back(j);
