#include <bits/stdc++.h>
using namespace std;

/*
We have points (x, y) with one of 4 types:
  U, D, L, R
When a proton reaches a point, its speed doubles and its direction becomes fixed
to the corresponding axis direction. Each point can be used at most once.

We may choose any initial position and direction. Initial speed is 1, so after
using k force points, final speed is 2^k. Therefore we only need the maximum
number of points that can be visited in a valid trajectory.

A trajectory is a polyline consisting of axis-parallel segments. After visiting
a point:
  U : next movement is along +y on same x
  D : next movement is along -y on same x
  R : next movement is along +x on same y
  L : next movement is along -x on same y

Thus there is a directed edge A -> B iff B is the first point encountered from A
in A's outgoing ray (same row/column and proper direction). Also, since the
initial position/direction is arbitrary, we may start at any point. So answer is
the maximum number of vertices in a directed path in this graph.

Important observation:
Each vertex has outdegree at most 1.
The graph is a functional digraph (possibly with sinks if no next point).
The maximum path length in such a graph equals:
- if starting in a tree leading to a cycle: distance to cycle + cycle size
- if starting elsewhere: analogous
So we can compute dp[v] = maximum number of distinct vertices visitable starting
from v.

Construction of next[v]:
For each x, sort points on that vertical line by y.
  nearest above / below gives candidates for U/D.
For each y, sort points on that horizontal line by x.
  nearest right / left gives candidates for R/L.

Then solve on functional graph with DFS states:
  0 unvisited, 1 visiting, 2 done
When encountering a back edge to a visiting node, we found a cycle; assign all
cycle nodes dp = cycle_size. For nodes leading into processed nodes, dp[u]=dp[next]+1.

Complexity: O(N log N)
*/

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;
    vector<long long> x(N), y(N);
    vector<char> t(N);

    for (int i = 0; i < N; ++i) {
        cin >> x[i] >> y[i] >> t[i];
    }

    vector<int> nxt(N, -1);

    unordered_map<long long, vector<pair<long long,int>>> byX, byY;
    byX.reserve(N * 2);
    byY.reserve(N * 2);

    for (int i = 0; i < N; ++i) {
        byX[x[i]].push_back({y[i], i});
        byY[y[i]].push_back({x[i], i});
    }

    for (auto &kv : byX) {
        auto &vec = kv.second;
        sort(vec.begin(), vec.end());
        int m = (int)vec.size();
        for (int i = 0; i < m; ++i) {
            int id = vec[i].second;
            if (t[id] == 'U') {
                if (i + 1 < m) nxt[id] = vec[i + 1].second;
            } else if (t[id] == 'D') {
                if (i - 1 >= 0) nxt[id] = vec[i - 1].second;
            }
        }
    }

    for (auto &kv : byY) {
        auto &vec = kv.second;
        sort(vec.begin(), vec.end());
        int m = (int)vec.size();
        for (int i = 0; i < m; ++i) {
            int id = vec[i].second;
            if (t[id] == 'R') {
                if (i + 1 < m) nxt[id] = vec[i + 1].second;
            } else if (t[id] == 'L') {
                if (i - 1 >= 0) nxt[id] = vec[i - 1].second;
            }
        }
    }

    vector<int> state(N, 0), dp(N, 0), posInStack(N, -1);
    vector<int> st;

    function<void(int)> dfs = [&](int u) {
        state[u] = 1;
        posInStack[u] = (int)st.size();
        st.push_back(u);

        int v = nxt[u];
        if (v == -1) {
            dp[u] = 1;
        } else if (state[v] == 0) {
            dfs(v);
            if (state[u] != 2) dp[u] = dp[v] + 1;
        } else if (state[v] == 1) {
            int start = posInStack[v];
            int cycSize = (int)st.size() - start;
            for (int i = start; i < (int)st.size(); ++i) {
                int node = st[i];
                dp[node] = cycSize;
                state[node] = 2;
            }
            if (state[u] != 2) dp[u] = dp[v] + 1;
        } else { // state[v] == 2
            dp[u] = dp[v] + 1;
        }

        if (state[u] != 2) state[u] = 2;
        st.pop_back();
        posInStack[u] = -1;
    };

    int ans = 0;
    for (int i = 0; i < N; ++i) {
        if (state[i] == 0) dfs(i);
        ans = max(ans, dp[i]);
    }

    cout << ans << '\n';
    return 0;
}

