import java.util.*;

/*
 * JAG 2015 - Force Point
 *
 * We need the maximum possible number of force points a proton can touch.
 * Each touched force point doubles the speed, so if it touches k points,
 * final speed = 2^k and the required answer is k = log2(speed).
 *
 * Motion rule:
 * - Proton moves along one of 4 axis directions.
 * - At a force point, it changes to the fixed direction of that point.
 * - Each point can be used at most once.
 *
 * Thus, if we regard each force point as a node, there is a directed edge
 * i -> j if after leaving point i in its direction, point j is the first
 * force point encountered on that ray. Also a proton may start from anywhere,
 * so any node can be the first touched point. Therefore the answer is the
 * maximum number of distinct nodes visitable along this functional graph.
 *
 * Since every node has out-degree at most 1, the graph is a functional graph.
 * The maximum path length in a functional graph equals:
 *   size(cycle) + maximum distance from any node in reverse trees into that cycle
 * maximizing over all cycles.
 *
 * Build outgoing edges efficiently:
 * For each x, sort points on that vertical line by y.
 * For each y, sort points on that horizontal line by x.
 * Then nearest neighbor in each of 4 directions is immediate predecessor/successor.
 *
 * Directions are encoded:
 *   U: +y, D: -y, R: +x, L: -x
 *
 * Complexity: O(n log n)
 */
public class Main {
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            if (c == -1) return null;
            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }

    static class Point {
        int id;
        int x, y;
        char d;
        Point(int id, int x, int y, char d) {
            this.id = id;
            this.x = x;
            this.y = y;
            this.d = d;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        String first = fs.next();
        if (first == null) return;
        int n = Integer.parseInt(first);

        Point[] pts = new Point[n];
        Map<Integer, ArrayList<Point>> byX = new HashMap<>();
        Map<Integer, ArrayList<Point>> byY = new HashMap<>();

        for (int i = 0; i < n; i++) {
            int x = fs.nextInt();
            int y = fs.nextInt();
            String s = fs.next();
            char d = s.charAt(0);
            pts[i] = new Point(i, x, y, d);

            byX.computeIfAbsent(x, k -> new ArrayList<>()).add(pts[i]);
            byY.computeIfAbsent(y, k -> new ArrayList<>()).add(pts[i]);
        }

        int[] up = new int[n];
        int[] down = new int[n];
        int[] left = new int[n];
        int[] right = new int[n];
        Arrays.fill(up, -1);
        Arrays.fill(down, -1);
        Arrays.fill(left, -1);
        Arrays.fill(right, -1);

        for (ArrayList<Point> list : byX.values()) {
            list.sort(Comparator.comparingInt(a -> a.y));
            for (int i = 0; i < list.size(); i++) {
                int id = list.get(i).id;
                if (i > 0) down[id] = list.get(i - 1).id;
                if (i + 1 < list.size()) up[id] = list.get(i + 1).id;
            }
        }

        for (ArrayList<Point> list : byY.values()) {
            list.sort(Comparator.comparingInt(a -> a.x));
            for (int i = 0; i < list.size(); i++) {
                int id = list.get(i).id;
                if (i > 0) left[id] = list.get(i - 1).id;
                if (i + 1 < list.size()) right[id] = list.get(i + 1).id;
            }
        }

        int[] to = new int[n];
        Arrays.fill(to, -1);
        for (int i = 0; i < n; i++) {
            switch (pts[i].d) {
                case 'U': to[i] = up[i]; break;
                case 'D': to[i] = down[i]; break;
                case 'L': to[i] = left[i]; break;
                case 'R': to[i] = right[i]; break;
            }
        }

        ArrayList<Integer>[] rev = new ArrayList[n];
        for (int i = 0; i < n; i++) rev[i] = new ArrayList<>();
        int[] indeg = new int[n];
        for (int i = 0; i < n; i++) {
            if (to[i] != -1) {
                rev[to[i]].add(i);
                indeg[to[i]]++;
            }
        }

        // Remove tree nodes, leaving only cycle nodes.
        boolean[] removed = new boolean[n];
        ArrayDeque<Integer> q = new ArrayDeque<>();
        for (int i = 0; i < n; i++) if (indeg[i] == 0) q.add(i);

        while (!q.isEmpty()) {
            int v = q.poll();
            removed[v] = true;
            int u = to[v];
            if (u != -1) {
                indeg[u]--;
                if (indeg[u] == 0) q.add(u);
            }
        }

        boolean[] seenCycle = new boolean[n];
        int answer = 0;

        for (int i = 0; i < n; i++) {
            if (!removed[i] && !seenCycle[i]) {
                // Collect one cycle
                ArrayList<Integer> cycle = new ArrayList<>();
                int cur = i;
                do {
                    seenCycle[cur] = true;
                    cycle.add(cur);
                    cur = to[cur];
                } while (cur != i);

                int cycleSize = cycle.size();

                // BFS/DFS on reverse trees rooted at cycle nodes, excluding cycle nodes.
                int bestDepth = 0;
                ArrayDeque<int[]> dq = new ArrayDeque<>();
                for (int v : cycle) {
                    dq.add(new int[]{v, 0});
                }

                while (!dq.isEmpty()) {
                    int[] st = dq.poll();
                    int v = st[0], depth = st[1];
                    bestDepth = Math.max(bestDepth, depth);
                    for (int pre : rev[v]) {
                        if (!removed[pre]) continue; // skip cycle predecessors
                        dq.add(new int[]{pre, depth + 1});
                    }
                }

                answer = Math.max(answer, cycleSize + bestDepth);
            }
        }

        // Also handle components with no cycle? Impossible in finite functional graph.
        // But isolated chains ending at -1 exist. Need longest path in those too.
        // DP on removed DAG toward sinks.
        int[] dp = new int[n];
        Arrays.fill(dp, -1);
        for (int i = 0; i < n; i++) {
            if (removed[i]) answer = Math.max(answer, dfsChain(i, to, dp));
        }

        System.out.println(answer);
    }

    static int dfsChain(int v, int[] to, int[] dp) {
        if (dp[v] != -1) return dp[v];
        if (to[v] == -1) return dp[v] = 1;
        return dp[v] = 1 + dfsChain(to[v], to, dp);
    }
}

