    xs = []
    ys = []
    for _ in range(n):
        x, y, d = input().split()
        x = int(x)
        y = int(y)
        points.append((x, y, d))
        xs.append(x)
        ys.append(y)

    # Coordinate compression
    xvals = sorted(set(xs))
    yvals = sorted(set(ys))
    x_id = {v: i for i, v in enumerate(xvals)}
    y_id = {v: i for i, v in enumerate(yvals)}

    # For each compressed x/y, store indices of points on that line
    on_x = [[] for _ in range(len(xvals))]
    on_y = [[] for _ in range(len(yvals))]
    for i, (x, y, d) in enumerate(points):
        on_x[x_id[x]].append(i)
        on_y[y_id[y]].append(i)

    # Build reverse graph:
    # If point i redirects motion to horizontal, then any later point j on same y can precede i.
    # If point i redirects motion to vertical, then any later point j on same x can precede i.
    rev = [[] for _ in range(n)]
    indeg = [0] * n

    horizontal_types = {'L', 'R'}
    vertical_types = {'U', 'D'}

    for i, (x, y, d) in enumerate(points):
        if d in horizontal_types:
            line = on_y[y_id[y]]
        else:
            line = on_x[x_id[x]]
        for j in line:
            if j == i:
                continue
            xj, yj, dj = points[j]
            # j can go to i iff after touching j, proton moves toward i along the shared line
            ok = False
            if xj == x:
                if dj == 'U' and y < yj:
                    ok = True
                elif dj == 'D' and y > yj:
                    ok = True
            elif yj == y:
                if dj == 'L' and x < xj:
                    ok = True
                elif dj == 'R' and x > xj:
                    ok = True
            if ok:
                rev[i].append(j)
                indeg[j] += 1

    # DP on DAG induced by strict movement along directed lines
    # dp[i] = max number of force points usable starting from i (including i)
    from collections import deque
    q = deque()
    dp = [1] * n

    # Nodes with indeg 0 in original reversed-edge processing order
    for i in range(n):
        if indeg[i] == 0:
            q.append(i)

    # Topological process on reversed graph
    while q:
        v = q.popleft()
        for u in rev[v]:
            if dp[u] < dp[v] + 1:
                dp[u] = dp[v] + 1
            indeg[u] -= 1
            if indeg[u] == 0:
                q.append(u)

    # We may start from outside and hit any first point, so answer is max chain length
    print(max(dp, default=0))

